#![deny(warnings)]
deno_ops_compile_test_runner::prelude!();

use deno_core::v8;
use deno_core::WebIDL;

// Type-checks the code generated by `#[derive(WebIDL)]` and `#[webidl]`.

#[allow(dead_code)]
#[derive(WebIDL)]
#[webidl(dictionary)]
struct WebIdlDictionary<'a> {
  #[webidl(default = 1)]
  first_value: u8,
  #[options(enforce_range = true)]
  second_value: u16,
  #[webidl(rename = "third")]
  renamed: Option<String>,
  #[webidl(required)]
  required: bool,
  value: v8::Local<'a, v8::Value>,
}

#[allow(dead_code)]
#[derive(WebIDL)]
#[webidl(enum)]
enum WebIdlChoice {
  FooBar,
  #[webidl(rename = "baz")]
  Other,
}

// Generated code must not depend on the names in scope where the derive is
// used, and member names must not clash with the names it binds internally.
mod shadowed {
  use deno_core::v8;
  use deno_core::WebIDL;

  #[allow(dead_code)]
  struct Ok;
  #[allow(dead_code)]
  struct Err;
  #[allow(dead_code)]
  struct None;

  #[allow(dead_code)]
  #[derive(WebIDL)]
  #[webidl(dictionary)]
  struct ShadowedDictionary<'a> {
    #[webidl(default = 1)]
    __input: u8,
    #[options(clamp = true)]
    __context: u8,
    #[webidl(required)]
    __scope: bool,
    __prefix: Option<String>,
    __value: v8::Local<'a, v8::Value>,
    #[webidl(default = 2)]
    __ctx: u8,
    #[options(enforce_range = true)]
    #[webidl(default = 3)]
    __options: u16,
  }

  #[allow(dead_code)]
  #[derive(WebIDL)]
  #[webidl(enum)]
  enum ShadowedEnum {
    Ok,
    #[webidl(rename = "none")]
    None,
  }
}

#[op2]
fn op_webidl_derive(
  #[webidl] choice: WebIdlChoice,
  #[webidl] values: Vec<u8>,
) -> Result<(), deno_core::error::AnyError> {
  let _ = (choice, values);
  Ok(())
}
